@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @oninput="OnSearchInput"
           value="@_query" />

    @if (_loading)
    {
        <div class="product-search-status">Searching…</div>
    }
    else if (_error is not null)
    {
        <div class="product-search-status product-search-error">
            Something went wrong. Please try again.
        </div>
    }
    else if (_results is not null && _results.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_results is { Count: > 0 })
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" loading="lazy" />
                    <div class="product-card-body">
                        <h4>@product.Name</h4>
                        <p>@product.Price.ToString("C")</p>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _query = string.Empty;
    private List<Product>? _results;
    private bool _loading;
    private Exception? _error;

    private CancellationTokenSource? _debounce;
    private CancellationTokenSource? _search;

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        _query = e.Value?.ToString() ?? string.Empty;

        // Cancel any pending debounce timer and in-flight search.
        _debounce?.Cancel();
        _debounce?.Dispose();
        _debounce = new CancellationTokenSource();

        var debounceCt = _debounce.Token;

        try
        {
            await Task.Delay(300, debounceCt);
        }
        catch (TaskCanceledException)
        {
            return; // User kept typing — wait for the next pause.
        }

        await ExecuteSearchAsync(_query);
    }

    private async Task ExecuteSearchAsync(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
        {
            _results = null;
            _error = null;
            _loading = false;
            return;
        }

        // Cancel any previous in-flight search.
        _search?.Cancel();
        _search?.Dispose();
        _search = new CancellationTokenSource();

        var ct = _search.Token;

        _loading = true;
        _error = null;

        try
        {
            _results = await ProductService.SearchAsync(query, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return; // Superseded by a newer search — discard silently.
        }
        catch (Exception ex)
        {
            _results = null;
            _error = ex;
        }
        finally
        {
            if (!ct.IsCancellationRequested)
            {
                _loading = false;
            }
        }
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    public void Dispose()
    {
        _debounce?.Cancel();
        _debounce?.Dispose();
        _search?.Cancel();
        _search?.Dispose();
    }
}

